pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty, address player) public {
        vm.assume(player != address(0) && player != address(c) && player != c.bank());
        vm.assume(timestamp > 0 && difficulty > 0);
        vm.warp(timestamp);
        vm.roll(difficulty);
        uint ticket = 10;
        vm.deal(player, ticket);
        vm.prank(player);
        (bool ok, ) = address(c).call{value: ticket}(abi.encodeWithSignature("play()"));
        uint balAfter = player.balance;
        bool paidOut = ok && c.pot() == 0;
        if (paidOut) {
            uint expectedGain = ticket - 1;
            assertTrue(balAfter == player.balance + expectedGain - ticket);
        } else {
            assertTrue(true);
        }
    }
}
